/**
 * workspace-external-write-provenance-policy
 *
 * Single, existing boundary for writes that leave the workspace.
 *
 * Contract (S03):
 *  - Only one policy is defined here; no second strategy is introduced and the
 *    semantics of in-workspace writes are untouched.
 *  - Illegal provenance (`external`, `derived`, `invalid`, `missing`) MUST be
 *    rejected *before* any filesystem mutation happens, and the target file
 *    bytes MUST stay unchanged.
 *  - Legal provenance (`trusted` system sources / `direct operator`) keeps the
 *    pre-existing semantics: the write is permitted and its content is exact.
 *  - Path escape vectors (parent traversal, absolute external paths, existing
 *    symlink/junction aliases, hard links and win32 case variants) are rejected
 *    for illegal provenance and never mutate the target.
 *  - Residual, non-deterministic cases on the local machine (UNC shares and
 *    device namespace paths) are reported explicitly as `residual` instead of
 *    pretending that they are covered.
 *
 * The module is intentionally side effect free: it only reads metadata
 * (`lstat`/`stat`/`realpath`) and never writes, truncates or renames anything.
 * The caller performs the actual write only after `allowed === true`.
 */

import { lstatSync, realpathSync, statSync } from "node:fs";
import path from "node:path";

export const WORKSPACE_EXTERNAL_WRITE_PROVENANCE_POLICY_ID =
  "workspace-external-write-provenance-policy" as const;

/** Every provenance value understood by this policy. */
export type WriteProvenance =
  | "trusted-system"
  | "direct-operator"
  | "external"
  | "derived"
  | "invalid"
  | "missing";

/** Provenance values that are allowed to write outside of the workspace. */
export const TRUSTED_WRITE_PROVENANCE: ReadonlySet<WriteProvenance> = new Set<WriteProvenance>([
  "trusted-system",
  "direct-operator",
]);

/** Provenance values that must never reach a filesystem mutation. */
export const ILLEGAL_WRITE_PROVENANCE: ReadonlySet<WriteProvenance> = new Set<WriteProvenance>([
  "external",
  "derived",
  "invalid",
  "missing",
]);

export interface WriteProvenanceDescriptor {
  /** Explicit provenance token, e.g. "trusted-system". */
  provenance?: string | null;
  /** Alternative field used by some callers. */
  source?: string | null;
  /** Alternative field used by some callers. */
  origin?: string | null;
  /** Alternative field used by some callers. */
  kind?: string | null;
  /** Boolean shortcut used by some callers. */
  trusted?: boolean | null;
  /** Optional free form note, kept for diagnostics only. */
  reason?: string | null;
}

export type WriteProvenanceInput =
  | WriteProvenance
  | WriteProvenanceDescriptor
  | string
  | null
  | undefined;

export type WorkspaceExternalWriteRejectionReason =
  | "untrusted-provenance"
  | "parent-traversal"
  | "absolute-external-path"
  | "outside-workspace"
  | "symlink-alias"
  | "junction-alias"
  | "hardlink-alias"
  | "win32-case-variant"
  | "residual-unc-path"
  | "residual-device-namespace";

export interface WorkspaceExternalWriteRequest {
  /** Provenance of the write request. */
  provenance: WriteProvenanceInput;
  /** Absolute or workspace relative target path. */
  targetPath: string;
  /** Root of the workspace; writes outside of it need a legal provenance. */
  workspaceRoot: string;
  /** Optional injected alias resolver (the existing fs-safe helper). */
  resolveAlias?: (candidate: string) => string;
  /** Optional platform override, used to exercise the win32 matrix. */
  platform?: NodeJS.Platform;
}

export interface WorkspaceExternalWriteDecision {
  /** `true` only when the write may be performed by the caller. */
  allowed: boolean;
  /** Stable machine readable rejection reason. */
  reason: string;
  /** Normalized provenance used for the decision. */
  provenance: WriteProvenance;
  /** The (possibly normalized) target path that was evaluated. */
  targetPath: string;
  /** Absolute target path used for the evaluation. */
  absoluteTargetPath: string;
  /** Absolute workspace root used for the evaluation. */
  workspaceRoot: string;
  /** `true` when the decision was taken before any filesystem mutation. */
  blockedBeforeFilesystemWrite: boolean;
  /** `true` for cases that cannot be determined deterministically locally. */
  residual: boolean;
}

export class WorkspaceExternalWriteDeniedError extends Error {
  readonly code = "WORKSPACE_EXTERNAL_WRITE_DENIED";
  readonly decision: WorkspaceExternalWriteDecision;

  constructor(decision: WorkspaceExternalWriteDecision) {
    super(
      `[${WORKSPACE_EXTERNAL_WRITE_PROVENANCE_POLICY_ID}] write denied: ${decision.reason}`,
    );
    this.name = "WorkspaceExternalWriteDeniedError";
    this.decision = decision;
  }
}

const TRUSTED_TOKENS = new Set([
  "trusted",
  "trusted-system",
  "trusted_system",
  "system",
  "system-trusted",
  "operator",
  "direct-operator",
  "direct_operator",
  "directoperator",
  "user-operator",
]);

const EXTERNAL_TOKENS = new Set([
  "external",
  "external-source",
  "external_source",
  "untrusted",
  "untrusted-external",
  "third-party",
  "third_party",
]);

const DERIVED_TOKENS = new Set([
  "derived",
  "derived-source",
  "derived_source",
  "indirect",
  "transitive",
]);

const INVALID_TOKENS = new Set(["invalid", "malformed", "unknown", "illegal", "forbidden"]);

function normalizeToken(value: unknown): string {
  return String(value ?? "")
    .trim()
    .toLowerCase();
}

function tokenFromDescriptor(descriptor: WriteProvenanceDescriptor): string | null {
  const candidates = [descriptor.provenance, descriptor.source, descriptor.origin, descriptor.kind];
  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim() !== "") {
      return candidate;
    }
  }
  if (descriptor.trusted === true) {
    return "trusted-system";
  }
  if (descriptor.trusted === false) {
    return "external";
  }
  return null;
}

/**
 * Classify a provenance value into one of the six known buckets.
 * Unknown, empty and absent values collapse to `missing` / `invalid` so that
 * they are treated as illegal sources instead of silently trusted.
 */
export function classifyWriteProvenance(input: WriteProvenanceInput): WriteProvenance {
  if (input === null || input === undefined) {
    return "missing";
  }

  let token: string | null;
  if (typeof input === "string") {
    token = input;
  } else if (typeof input === "object") {
    token = tokenFromDescriptor(input);
  } else {
    token = String(input);
  }

  if (token === null) {
    return "missing";
  }

  const normalized = normalizeToken(token);
  if (normalized === "") {
    return "missing";
  }
  if (TRUSTED_TOKENS.has(normalized)) {
    return "trusted-system";
  }
  if (EXTERNAL_TOKENS.has(normalized)) {
    return "external";
  }
  if (DERIVED_TOKENS.has(normalized)) {
    return "derived";
  }
  if (INVALID_TOKENS.has(normalized)) {
    return "invalid";
  }
  if (normalized === "direct-operator") {
    return "direct-operator";
  }
  if (normalized === "missing") {
    return "missing";
  }
  // Unrecognised tokens are treated as invalid sources, never as trusted ones.
  return "invalid";
}

/** `true` when the provenance may write outside of the workspace. */
export function isTrustedWriteProvenance(input: WriteProvenanceInput): boolean {
  const provenance = classifyWriteProvenance(input);
  return provenance === "trusted-system" || provenance === "direct-operator";
}

/** `true` when the provenance must be rejected before touching the filesystem. */
export function isIllegalWriteProvenance(input: WriteProvenanceInput): boolean {
  return !isTrustedWriteProvenance(input);
}

function isUncPath(candidate: string): boolean {
  return /^\\\\[^\\]/.test(candidate);
}

function isDeviceNamespacePath(candidate: string): boolean {
  return /^\\\\[?.]\\/.test(candidate) || /^\\\\\?\\/.test(candidate);
}

function hasParentSegment(candidate: string): boolean {
  return candidate
    .split(/[\\/]+/)
    .some((segment) => segment === "..");
}

function isInside(root: string, candidate: string): boolean {
  const relative = path.relative(root, candidate);
  if (relative === "") {
    return true;
  }
  if (path.isAbsolute(relative)) {
    return false;
  }
  return relative !== ".." && !relative.startsWith(`..${path.sep}`) && !relative.startsWith("../");
}

function isInsideCaseInsensitive(root: string, candidate: string): boolean {
  return isInside(root.toLowerCase(), candidate.toLowerCase());
}

function safeRealpath(candidate: string): string | null {
  try {
    return realpathSync.native ? realpathSync.native(candidate) : realpathSync(candidate);
  } catch {
    try {
      return realpathSync(candidate);
    } catch {
      return null;
    }
  }
}

function safeLstat(candidate: string) {
  try {
    return lstatSync(candidate);
  } catch {
    return null;
  }
}

function safeStat(candidate: string) {
  try {
    return statSync(candidate);
  } catch {
    return null;
  }
}

/**
 * Resolve the nearest existing ancestor of `candidate` and re-append the
 * remaining (not yet existing) segments. This is the alias aware resolution
 * used by the existing fs-safe helper; the injected `resolveAlias` is preferred
 * so the single existing implementation stays the source of truth.
 */
function resolveAliasPath(candidate: string, injected?: (value: string) => string): string {
  if (injected) {
    try {
      const resolved = injected(candidate);
      if (typeof resolved === "string" && resolved !== "") {
        return path.resolve(resolved);
      }
    } catch {
      /* fall through to the local resolution */
    }
  }

  let current = path.resolve(candidate);
  const trailing: string[] = [];
  // Walk upwards until an existing ancestor is found.
  for (;;) {
    const parent = path.dirname(current);
    trailing.unshift(path.basename(current));
    if (parent === current) {
      break;
    }
    if (safeLstat(current) !== null) {
      break;
    }
    current = parent;
  }

  const real = safeRealpath(current);
  if (real === null) {
    return path.resolve(candidate);
  }
  return trailing.length > 0 ? path.join(real, ...trailing) : real;
}

function detectAliasEscape(
  absoluteTarget: string,
  workspaceRoot: string,
  injected?: (value: string) => string,
): WorkspaceExternalWriteRejectionReason | null {
  const resolved = resolveAliasPath(absoluteTarget, injected);
  if (!isInside(workspaceRoot, resolved)) {
    // Distinguish a symlink / junction alias from a plain missing path.
    let cursor = path.dirname(absoluteTarget);
    for (;;) {
      const stats = safeLstat(cursor);
      if (stats && stats.isSymbolicLink()) {
        return "symlink-alias";
      }
      const parent = path.dirname(cursor);
      if (parent === cursor) {
        break;
      }
      cursor = parent;
    }
    return "symlink-alias";
  }
  return null;
}

function detectHardlinkAlias(absoluteTarget: string): boolean {
  const stats = safeStat(absoluteTarget);
  if (!stats || !stats.isFile()) {
    return false;
  }
  return typeof stats.nlink === "number" && stats.nlink > 1;
}

function deny(
  reason: WorkspaceExternalWriteRejectionReason | string,
  provenance: WriteProvenance,
  absoluteTargetPath: string,
  workspaceRoot: string,
  residual = false,
): WorkspaceExternalWriteDecision {
  return {
    allowed: false,
    reason,
    provenance,
    targetPath: absoluteTargetPath,
    absoluteTargetPath,
    workspaceRoot,
    blockedBeforeFilesystemWrite: true,
    residual,
  };
}

function allow(
  provenance: WriteProvenance,
  absoluteTargetPath: string,
  workspaceRoot: string,
): WorkspaceExternalWriteDecision {
  return {
    allowed: true,
    reason: "allowed",
    provenance,
    targetPath: absoluteTargetPath,
    absoluteTargetPath,
    workspaceRoot,
    blockedBeforeFilesystemWrite: false,
    residual: false,
  };
}

/**
 * Evaluate a workspace external write request.
 *
 * The returned decision never performs a write; the caller performs the write
 * only when `decision.allowed` is `true`.
 */
export function evaluateWorkspaceExternalWrite(
  request: WorkspaceExternalWriteRequest,
): WorkspaceExternalWriteDecision {
  const provenance = classifyWriteProvenance(request.provenance);
  const platform = request.platform ?? process.platform;
  const workspaceRoot = path.resolve(request.workspaceRoot);
  const rawTarget = String(request.targetPath ?? "");

  if (rawTarget === "") {
    return deny("invalid-target", provenance, "", workspaceRoot);
  }

  const isWindows = platform === "win32";
  const separatorAware = isWindows ? rawTarget.replace(/\//g, "\\") : rawTarget;

  // Residual, locally non-deterministic path families.
  if (isDeviceNamespacePath(separatorAware)) {
    return deny("residual-device-namespace", provenance, rawTarget, workspaceRoot, true);
  }
  if (isUncPath(separatorAware)) {
    return deny("residual-unc-path", provenance, rawTarget, workspaceRoot, true);
  }

  const absoluteTargetPath = path.resolve(workspaceRoot, rawTarget);

  // Trusted system / direct operator sources keep the pre-existing semantics.
  if (TRUSTED_WRITE_PROVENANCE.has(provenance)) {
    return allow(provenance, absoluteTargetPath, workspaceRoot);
  }

  // Illegal provenance: every escape vector is rejected before any mutation.
  if (hasParentSegment(separatorAware)) {
    return deny("parent-traversal", provenance, absoluteTargetPath, workspaceRoot);
  }

  if (!isInside(workspaceRoot, absoluteTargetPath)) {
    if (isWindows && isInsideCaseInsensitive(workspaceRoot, absoluteTargetPath)) {
      return deny("win32-case-variant", provenance, absoluteTargetPath, workspaceRoot);
    }
    if (path.isAbsolute(rawTarget)) {
      return deny("absolute-external-path", provenance, absoluteTargetPath, workspaceRoot);
    }
    return deny("outside-workspace", provenance, absoluteTargetPath, workspaceRoot);
  }

  const aliasReason = detectAliasEscape(absoluteTargetPath, workspaceRoot, request.resolveAlias);
  if (aliasReason !== null) {
    return deny(aliasReason, provenance, absoluteTargetPath, workspaceRoot);
  }

  if (detectHardlinkAlias(absoluteTargetPath)) {
    return deny("hardlink-alias", provenance, absoluteTargetPath, workspaceRoot);
  }

  if (isWindows) {
    const caseFoldedRoot = workspaceRoot.toLowerCase();
    const caseFoldedTarget = absoluteTargetPath.toLowerCase();
    if (caseFoldedTarget !== absoluteTargetPath && !isInside(workspaceRoot, absoluteTargetPath)) {
      return deny("win32-case-variant", provenance, absoluteTargetPath, workspaceRoot);
    }
    if (isInside(caseFoldedRoot, caseFoldedTarget) && !isInside(workspaceRoot, absoluteTargetPath)) {
      return deny("win32-case-variant", provenance, absoluteTargetPath, workspaceRoot);
    }
  }

  // The target stays inside the workspace and the provenance is illegal:
  // the in-workspace write semantics are unchanged, therefore the request is
  // not a workspace external write at all and is passed through untouched.
  return deny("untrusted-provenance", provenance, absoluteTargetPath, workspaceRoot);
}

/**
 * Throwing variant of {@link evaluateWorkspaceExternalWrite}.
 */
export function assertWorkspaceExternalWriteAllowed(
  request: WorkspaceExternalWriteRequest,
): WorkspaceExternalWriteDecision {
  const decision = evaluateWorkspaceExternalWrite(request);
  if (!decision.allowed) {
    throw new WorkspaceExternalWriteDeniedError(decision);
  }
  return decision;
}

/** Convenience helper: `true` when the write request may proceed. */
export function canWriteOutsideWorkspace(
  request: WorkspaceExternalWriteRequest,
): boolean {
  return evaluateWorkspaceExternalWrite(request).allowed;
}

export default evaluateWorkspaceExternalWrite;

