  return /^\\\\[?.]\\/.test(candidate) || /^\\\\\?\\/.test(candidate);
}

function hasParentSegment(candidate: string): boolean {
  return candidate
    .split(/[\\/]+/)
    .some((segment) => segment === "..");
}

